p=Path(__file__).parent;text={}
def e(k,t,tag='p',cls=''):text[k]=t;return f'<{tag} data-edit="{k}" class="{cls}">{t}</{tag}>'
def head(k,n):return '<div class="mast">'+e('mast','重新看见岸线／虚构计划','span')+e(k+'-page',n,'span','page-number')+'</div>'
