def line(k):return f'<svg class="rule-line" data-plane="{k}" viewBox="0 0 1000 30" aria-hidden="true"></svg>'
css=''' :root{--canvas:#f6f5f1;--surface:#fff;--ink:#17201b;--muted:#5b675f;--rule:#d0d5cc;--accent:#96512f;--accentSoft:#ecd9ca;--accentInk:#703717;--titleSize:104px}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--canvas);font-family:system-ui,-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei","Noto Sans CJK SC",sans-serif}button,input,select,textarea{font:inherit;max-width:100%;min-width:0}button{padding:9px 13px;min-height:44px;background:var(--surface);color:var(--ink);border:1px solid var(--rule);cursor:pointer}a{color:inherit}:focus-visible{outline:3px solid var(--accent);outline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:8px;padding:12px 24px;background:var(--surface)}nav a{padding:10px;text-decoration:none}nav a[aria-current]{background:var(--ink);color:var(--canvas)}.status{padding:12px 24px;font-size:14px;border-bottom:1px solid var(--rule)}main{max-width:1440px;margin:auto}.page{padding:36px 64px 30px;min-height:900px;display:flex;flex-direction:column;background:var(--canvas)}.page[hidden]{display:none}body.overview .page[hidden]{display:flex}body.overview .page{margin-bottom:32px;border-bottom:1px solid var(--rule)}.mast{display:flex;justify-content:space-between;gap:25px;font-size:20px;line-height:1.5;color:var(--muted);margin-bottom:76px}.page-number,.index{font-family:ui-monospace,"SFMono-Regular",Consolas,"Liberation Mono",monospace}h1,h2,h3,p{margin-top:0}h1{font-size:var(--titleSize);font-weight:650;letter-spacing:-.025em;line-height:1.14;margin:20px 0 110px;max-width:1180px}h1 span{display:block}h2{font-size:68px;line-height:1.2;font-weight:650;letter-spacing:-.025em;margin-bottom:60px}h3{font-size:48px;line-height:1.3;font-weight:600;margin-bottom:24px}p{font-size:26px;line-height:1.65;margin-bottom:26px}.cover-bottom{display:grid;grid-template-columns:minmax(0,4fr) minmax(0,6fr);gap:56px}.cover-bottom .subtitle{font-size:40px;line-height:1.4}.rule-line line{vector-effect:non-scaling-stroke}.rule-line{display:block;width:100%;height:auto;min-height:20px;margin:20px 0 0}.range-group{margin-bottom:34px}.range-content{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,4fr) minmax(0,4fr);gap:40px;margin-top:22px;align-items:start}.index{font-size:20px;color:var(--muted);line-height:1.5}.range-content p{margin-bottom:12px}.time-group{background:var(--accentSoft);color:var(--accentInk);text-align:center;padding:35px 40px 40px;margin:0 8.5% 38px;break-inside:avoid}.time-label{font-size:26px;margin-bottom:12px}.time-number{font-size:132px;font-weight:650;letter-spacing:-.025em;line-height:1.1;margin:0}.time-limit{font-size:36px;line-height:1.4;margin:24px 0 0}.time-copy{max-width:860px;margin:0 auto}.notes-layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(0,6fr);gap:112px}.notes-layout h2{font-size:72px;line-height:1.25;margin-bottom:30px}.notes-layout h3{font-size:32px;margin-bottom:12px}.notes-layout section{margin-bottom:40px}.notes-layout .ending{margin-top:45px}.notes-intro{max-width:390px}.notes-aside .rule-line{max-width:220px}footer{font-size:20px;line-height:1.5;color:var(--muted);margin-top:auto;padding-top:35px}.editor{max-width:1440px;margin:24px auto;background:var(--surface);padding:22px;border:1px solid var(--rule)}summary{font-size:20px;cursor:pointer}.tools{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:18px 0}.tools label{display:flex;gap:8px;align-items:center;flex-wrap:wrap;min-width:0;max-width:100%}.tools input[type=file]{width:230px;max-width:100%}.geometry{border-top:1px solid var(--rule);margin-top:24px;padding-top:20px}.geometry textarea{width:100%;min-height:70px;padding:12px}.tool-note{font-size:16px;margin:18px 0 0}.editing [data-edit]{outline:1px dashed var(--accent);outline-offset:4px}[data-edit]{overflow-wrap:break-word;word-break:normal;line-break:strict}.notes-layout h2{overflow-wrap:normal;line-break:strict}.mono main{filter:grayscale(1)}body.hide-decoration .rule-line{visibility:hidden}.editor-footer{padding:16px;text-align:center;font-size:14px}@media(max-width:1000px){.page{padding:36px 40px}h1{font-size:min(var(--titleSize),90px);margin-bottom:75px}h2{font-size:54px}.range-content{grid-template-columns:2fr 4fr 5fr;gap:24px}.range-content h3{font-size:38px}.notes-layout{gap:50px;grid-template-columns:3fr 5fr}.notes-layout h2{font-size:56px}.time-number{font-size:110px}}@media(max-width:750px){nav{gap:0;padding:8px}nav a{font-size:14px;padding:9px}.status{padding:12px 20px}.page{padding:30px 22px;min-height:0}.mast{font-size:18px;margin-bottom:40px}h1{font-size:min(var(--titleSize),62px);margin:10px 0 55px}h2,.notes-layout h2{font-size:40px;margin-bottom:35px}p{font-size:20px;line-height:1.65}.cover-bottom{display:block}.cover-bottom .subtitle{font-size:30px}.range-content{display:block;margin-top:15px}.index{font-size:18px;margin-bottom:18px!important}.range-content h3{font-size:32px;margin-bottom:18px}.range-group{margin-bottom:24px}.time-group{margin:0 0 30px;padding:30px 14px}.time-label{font-size:22px}.time-number{font-size:78px}.time-limit{font-size:26px;margin-top:20px}.notes-layout{display:block}.notes-aside{margin-bottom:35px}.notes-aside .rule-line{display:none}.notes-layout h3{font-size:28px}.notes-layout section{margin-bottom:30px}.notes-layout .ending{margin-top:30px}footer{font-size:18px;padding-top:25px}.editor{margin:20px 0;padding:20px}.tools label{width:100%}.tool-note{font-size:15px}}@media print{nav,.status,.editor,.editor-footer{display:none}.page,.page[hidden]{display:flex!important;break-after:page;min-height:0}}'''
body='<nav>'+''.join(f'<a href="#{k}" data-page="{k}">{i:02} {n}</a>' for i,(k,n) in enumerate([('cover','问题'),('range','范围'),('time','时间'),('notes','待补')],1))+'</nav><div class="status">MiMo v2.0 的 AI 应用候选｜基线来源：人工精修｜原效果评价：差／适配二级｜不新增语言或版本</div><main>'
body+='<section class="page" id="cover">'+head('a','01')+'<h1>'+e('title','重新看见','span')+e('title-second','岸线','span')+'</h1><div class="cover-bottom">'+e('a-subtitle','从一个问题开始。','p','subtitle')+e('a-body','我们想怎样观察岸线？先说清对象与安排，再决定怎样记录。这是一份尚待补足的计划，没有现场结果。')+'</div>'+line('a')+foot()+'</section>'
body+='<section class="page" id="range">'+head('b','02')+e('b-title','有了数量，还需要范围。','h2')
for k,i,t,v in [('b1','01／观察对象','12个观察点','目前只有数量。每个点的名称与位置尚未确定。'),('b2','02／记录安排','3轮记录','轮次与点位怎样对应仍需说明；不能据此直接推出36份记录，也不表示已经完成。')]:body+='<section class="range-group">'+line(k)+'<div class="range-content">'+e(k+'-index',i,'p','index')+e(k+'-title',t,'h3')+e(k+'-body',v)+'</div></section>'
body+=foot()+'</section><section class="page" id="time">'+head('c','03')+e('c-title','这段时间，指向哪里？','h2')+'<div class="time-group">'+e('c-label','时间设定','p','time-label')+e('c-number','30分钟','p','time-number')+e('c-limit','适用范围待定','p','time-limit')+'</div><div class="time-copy">'+e('c-body','它属于单点、单轮，还是整个活动？目前没有说明，也不能把3轮记录换算为每轮10分钟。')+e('c-end','先说明适用范围，再决定起止边界。')+'</div>'+foot()+'</section>'
body+='<section class="page" id="notes">'+head('d','04')+'<div class="notes-layout"><div class="notes-aside">'+e('d-title','把说明补齐。','h2')+e('d-intro','接下来，需要回答三件事。','p','notes-intro')+line('d')+'</div><div>'
for n,(t,v) in enumerate([('点位','给12个观察点补上名称与位置。'),('轮次','说明3轮记录如何安排，以及怎样对应点位。'),('时间','界定时间设定30分钟的适用范围；目前仍待确定。')]):body+='<section>'+e(f'd-title-{n}',t,'h3')+e(f'd-body-{n}',v)+'</section>'
body+=e('d-end','这些信息明确后，才能继续安排记录。版面结束，不代表观察已经完成。','p','ending')+'</div></div>'+foot()+'</section></main>'
roles=['canvas','surface','ink','muted','rule','accent','accentSoft','accentInk']
body+='''<details class="editor"><summary>编辑与导出</summary><div class="tools"><button id="edit" aria-pressed="false">编辑文字</button><button id="overview" aria-pressed="false">四页并看</button><button id="mono" aria-pressed="false">黑白检查</button><button id="decoration" aria-pressed="false">隐藏分隔线</button><button id="reset">恢复初始版本</button></div><div class="tools"><label>分支 skin<select id="skin"><option value="rational-humanistic">理性人文</option><option value="dark-tech">暗黑科技</option></select></label><label>封面标题显式字号<input type="number" id="title-size" min="48" max="160"></label><button id="clear-overrides">清除显式颜色覆盖</button></div><div class="tools">'''+''.join(f'<label>{k}<input type="color" id="{k}"></label>' for k in roles)+'''</div><div class="geometry"><label>独立分隔线<select id="shape"></select></label><p class="tool-note">参数：x1,y1,x2,y2,线宽，坐标基于1000×30画布。分隔线独立于文字，不代表路线或进度。</p><textarea id="points" aria-label="线条参数"></textarea><div class="tools"><label>绑定色角色<select id="fill">'''+''.join(f'<option>{k}</option>' for k in roles)+'''</select></label><button id="apply-shape">应用对象修改</button></div></div><div class="tools"><button id="json-export">下载编辑数据 JSON</button><button id="html-export">下载可编辑 HTML</button><label>导入 JSON<input id="json-import" type="file" accept=".json,application/json"></label></div><p class="tool-note">换肤只改绑定色角色，保留文字、几何及显式颜色/字号覆盖。本候选默认静态，不删改MiMo原有运动语言和时间线。布局与组件仍可选，资源共享规则不变。</p><p id="edit-status" role="status" class="tool-note">当前是同一MiMo的AI应用候选；canonical仍为languages/mimo/v2.0。无动画，暂停不适用。</p></details><div class="editor-footer">MiMo v2.0 应用研究｜基线规范不随本包复制，不改canonical，不并入其他语言。</div>'''
parser=argparse.ArgumentParser();parser.add_argument('--canonical-root',type=Path,required=True);args=parser.parse_args();canon=args.canonical_root/'kit/design-language.json';c=json.loads(canon.read_text());themes={k:{r:v['color'][r] for r in roles} for k,v in c['branches'].items()}
shapes=[dict(id=id,page=k,points='0,15,1000,15,1.5',fill='rule',stroke=False) for k,id in [('a','封面短线'),('b1','观察对象分隔'),('b2','记录安排分隔'),('d','末页短线')]];shapes[-1]['points']='0,15,800,15,3';shapes[-1]['fill']='accent'
model=dict(schemaVersion=1,designVersion='MIMO-APPLICATION-01',canonicalReference='languages/mimo/v2.0',baselineSource='人工精修',applicationSource='AI应用候选',qualityTag='差',adaptationLevel=2,candidate=True,text=text,skin='rational-humanistic',overrides={},titleSize=104,colors=themes['rational-humanistic'],shapes=shapes)
for k in ['a','b1','b2','d']:
 x=next(x for x in shapes if x['page']==k);a,b,cc,d,w=x['points'].split(',');body=body.replace(f'viewBox="0 0 1000 30" aria-hidden="true"></svg>',f'viewBox="0 0 1000 30" aria-hidden="true"><line x1="{a}" y1="{b}" x2="{cc}" y2="{d}" stroke-width="{w}" stroke="{model["colors"][x["fill"]]}"></line></svg>',1)
(p/'index.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>重新看见岸线 · MiMo应用候选</title><style>'+css+'</style></head><body>'+body+'<script id="themes" type="application/json">'+json.dumps(themes)+'</script><script id="model" type="application/json">'+json.dumps(model,ensure_ascii=False).replace('<','\\u003c')+'</script><script>'+(p/'app.js').read_text()+'</script></body></html>')
